00049 struct HEVCNalType {
00050     enum Enum {
00051         CodedSlice_Trail_N = 0,
00052         CodedSlice_Trail_R = 1,
00053         CodedSlice_TSA_N = 2,
00054         CodedSlice_TLA_R = 3,
00055         CodedSlice_STSA_N = 4,
00056         CodedSlice_STSA_R = 5,
00057         CodedSlice_RADL_N = 6,
00058         CodedSlice_RADL_R = 7,
00059         CodedSlice_RASL_N = 8,
00060         CodedSlice_RASL_R = 9,
00061         RSV_VCL_N10 = 10,
00062         RSV_VCL_N12 = 12,
00063         RSV_VCL_N14 = 14,
00064         // Reserved (11,13,15)
00065         CodedSlice_BLA_W_LP = 16,
00066         CodedSlice_BLA_W_RADL = 17,
00067         CodedSlice_BLA_N_LP = 18,
00068         CodedSlice_IDR_W_RADL = 19,
00069         CodedSlice_IDR_N_LP = 20,
00070         CodedSlice_CRA = 21,
00071         RSV_IRAP_VCL22 = 22,
00072         RSV_IRAP_VCL23 = 23,
00073         // Reserved (22-31)
00074         VPS = 32,
00075         SPS = 33,
00076         PPS = 34,
00077         AUD = 35,
00078         EndOfSequence = 36,
00079         EndOfBitstream = 37,
00080         FillerData = 38,
00081         PrefixSEI = 39,
00082         SuffixSEI = 40
00083         // Reserved (41-47)
00084         // Unspecified (48-63)
00085     };
00086 };
